practice.solution:
def astar_cost(graph, h, start, goal):
    best = {start: 0}
    frontier = [(h[start], start)]
    while frontier:
        k = 0
        for i in range(len(frontier)):
            if frontier[i][0] < frontier[k][0]:
                k = i
        f, n = frontier.pop(k)
        if n == goal:
            return best[n]
        if f > best[n] + h[n]:
            continue
        for m in graph[n]:
            g = best[n] + graph[n][m]
            if m not in best or g < best[m]:
                best[m] = g
                frontier.append((g + h[m], m))
    return -1

