def entails(kb, alpha, symbols):
    n = len(symbols)
    for mask in range(2 ** n):
        m = {}
        for i in range(n):
            m[symbols[i]] = (mask >> i) & 1 == 1
        def val(lit):
            if lit[0] == '-':
                return not m[lit[1:]]
            return m[lit]
        def holds(cl):
            for lit in cl:
                if val(lit):
                    return True
            return False
        good = True
        for cl in kb:
            if not holds(cl):
                good = False
        if good and not holds(alpha):
            return False
    return True

