        t = s[t]
    return t

def unify(a, b):
    s = {}
    def go(x, y):
        x = walk(x, s)
        y = walk(y, s)
        if x == y:
            return True
        if is_var(x):
            s[x] = y
            return True
        if is_var(y):
            s[y] = x
            return True
        if isinstance(x, list) and isinstance(y, list) and len(x) == len(y) and x[0] == y[0]:
            for i in range(1, len(x)):
                if not go(x[i], y[i]):
                    return False
            return True
        return False
    if go(a, b):
        return [[k, s[k]] for k in sorted(s)]
    return 'fail'

