def plan_length(state, goal, actions):
    start = tuple(sorted(set(state)))
    seen = {start: 0}
    queue = [start]
    i = 0
    while i < len(queue):
        cur = queue[i]
        i += 1
        ok = True
        for g in goal:
            if g not in cur:
                ok = False
        if ok:
            return seen[cur]
        for pre, add, dele in actions:
            good = True
            for p in pre:
                if p not in cur:
                    good = False
            if good:
                s = set(cur)
                for d in dele:
                    s.discard(d)
                for a in add:
                    s.add(a)
                nxt = tuple(sorted(s))
                if nxt not in seen:
                    seen[nxt] = seen[cur] + 1
                    queue.append(nxt)
    return -1

