def value_iteration(P, R, gamma, iters):
    n = len(R)
    U = [0.0] * n
    for _ in range(iters):
        new = []
        for s in range(n):
            best = None
            for a in P[s]:
                q = 0.0
                for p, s2 in a:
                    q += p * U[s2]
                if best is None or q > best:
                    best = q
            if best is None:
                best = 0.0
            new.append(R[s] + gamma * best)
        U = new
    return [round(x, 6) for x in U]

