practice.solution:
import math
def entropy(counts):
    t = sum(counts)
    if t == 0:
        return 0.0
    h = 0.0
    for c in counts:
        if c > 0:
            p = c / t
            h -= p * math.log(p) / math.log(2)
    return round(h, 9)

